          p.style.backgroundSize = `${m.w}mm ${m.h}mm`;
          p.style.backgroundPosition = `${m.x}mm ${m.y}mm`;
          p.style.backgroundRepeat = "no-repeat";
          p.classList.toggle("imode", mode === "i");
          b.style.cssText = `left:${m.x}mm;top:${m.y}mm;width:${m.w}mm;height:${m.h}mm;display:${mode === "i" && on ? "block" : "none"}`;
